const unsigned g_gxm_abi_count = 100u;

const gxm_abi_entry* gxm_abi_lookup(uint32_t stub_va) {
    unsigned lo = 0u, hi = GXM_ABI_ENTRY_COUNT;
    while (lo < hi) {
        const unsigned mid = lo + (hi - lo) / 2u;
        const gxm_abi_entry* e = &g_gxm_abi_table[mid];
        if (e->stub == stub_va) return e;
        if (e->stub < stub_va) lo = mid + 1u; else hi = mid;
    }
    return nullptr;
}

uint32_t gxm_abi_dispatch(uint32_t stub_va, uint32_t* regs, uint32_t* stack_args) {
    const gxm_abi_entry* e = gxm_abi_lookup(stub_va);
    if (e == nullptr) return 0u;   // unmapped stub
    return e->fn(regs, stack_args);
}
